138	// Screen pixels per image pixel at each zoom step: 100% up to 3200%.
139	const ZOOM_STEPS = [1, 2, 4, 8, 16, 32];
140	// From this zoom on, an image pixel is large enough to read as a square, so the
141	// image renders pixelated and the grid appears. The Paper note leaves the exact
142	// threshold open; 800% is the pick.
143	const PIXEL_ZOOM = 8;
