145	type Size = { width: number; height: number };
146	type Offset = { x: number; y: number };
147	
148	// Pan moves the image only as far as it overhangs the frame, so the frame stays
149	// covered. An image smaller than the frame in one axis stays centred on it.
150	function clampPan(pan: Offset, shown: Size, frame: Size): Offset {
151	  const maxX = Math.max(0, (shown.width - frame.width) / 2);
152	  const maxY = Math.max(0, (shown.height - frame.height) / 2);
153	  return {
154	    x: Math.min(maxX, Math.max(-maxX, pan.x)),
155	    y: Math.min(maxY, Math.max(-maxY, pan.y)),
156	  };
157	}
