159	// Zoom and pan live here, not in the overlay, so panning re-renders only this
160	// stage. The key on the caller resets zoom when the shown item changes.
161	function ZoomableImage({
162	  src,
163	  originalSrc,
164	  alt,
165	}: {
166	  src: string;
167	  /** The full-size file. Swapped in once the image is zoomed past fit. */
168	  originalSrc?: string;
169	  alt: string;
170	}) {
171	  const frameRef = useRef<HTMLDivElement>(null);
172	  const dragRef = useRef<{ pointerX: number; pointerY: number; origin: Offset } | null>(null);
173	  const [frame, setFrame] = useState<Size | null>(null);
174	  // The thumbnail's size. It fixes the layout box, so the original can swap in
175	  // without the picture moving or resizing.
176	  const [natural, setNatural] = useState<Size | null>(null);
177	  const [original, setOriginal] = useState<{ url: string; width: number } | null>(null);
178	  // null means fit, which follows the frame as the window resizes.
179	  const [zoomLevel, setZoomLevel] = useState<number | null>(null);
180	  const [pan, setPan] = useState<Offset>({ x: 0, y: 0 });
181	  const [isDragging, setIsDragging] = useState(false);
182	
183	  useEffect(() => {
184	    const element = frameRef.current;
185	    if (!element) return;
186	    const observer = new ResizeObserver((entries) => {
187	      const rect = entries[0]?.contentRect;
188	      if (!rect) return;
189	      setFrame((previous) =>
190	        previous && previous.width === rect.width && previous.height === rect.height
191	          ? previous
192	          : { width: rect.width, height: rect.height },
193	      );
194	    });
195	    observer.observe(element);
196	    return () => observer.disconnect();
197	  }, []);
198	
199	  const ready = frame !== null && natural !== null;
200	  const fit =
201	    ready && frame.width > 0 && frame.height > 0
202	      ? Math.min(frame.width / natural.width, frame.height / natural.height)
203	      : 1;
204	  const zoom = Math.max(fit, zoomLevel ?? fit);
205	  const isZoomed = zoom > fit;
206	  const shown = natural ? { width: natural.width * zoom, height: natural.height * zoom } : null;
207	  const offset = ready && shown ? clampPan(pan, shown, frame) : { x: 0, y: 0 };
208	  const showPixels = ready && zoom >= PIXEL_ZOOM;
209	  // How many original pixels sit in one thumbnail pixel. The pixel grid draws
210	  // one cell per original pixel, so it lines up with what is on screen.
211	  const sourceScale = original && natural ? original.width / natural.width : 1;
212	  const displayedSrc = original?.url ?? src;
213	  // The layout box is the thumbnail's fitted size, set explicitly so a larger
214	  // original cannot change it.
215	  const base =
216	    ready && natural
217	      ? { width: natural.width * Math.min(1, fit), height: natural.height * Math.min(1, fit) }
218	      : null;
219	
220	  // Past fit, load the original. It is decoded before the swap, so the picture
221	  // never flashes back to empty.
222	  useEffect(() => {
223	    if (!isZoomed || original || !originalSrc || originalSrc === src) return;
224	    let cancelled = false;
225	    const probe = new Image();
226	    probe.src = originalSrc;
227	    probe.decode().then(
228	      () => {
229	        if (!cancelled) setOriginal({ url: originalSrc, width: probe.naturalWidth });
230	      },
231	      () => undefined,
232	    );
233	    return () => {
234	      cancelled = true;
235	    };
236	  }, [isZoomed, original, originalSrc, src]);
237	
238	  const nextStep = ZOOM_STEPS.find((step) => step > zoom);
239	  const previousStep = [...ZOOM_STEPS].reverse().find((step) => step < zoom);
240	  const zoomOutLevel = previousStep !== undefined && previousStep > fit ? previousStep : null;
241	
242	  function applyZoom(nextLevel: number | null) {
243	    if (ready) {
244	      const next = Math.max(fit, nextLevel ?? fit);
245	      // Keep the point at the centre of the frame in place as the scale changes.
246	      const scaled = { x: (offset.x * next) / zoom, y: (offset.y * next) / zoom };
247	      setPan(
248	        clampPan(scaled, { width: natural.width * next, height: natural.height * next }, frame),
249	      );
250	    }
251	    setZoomLevel(nextLevel);
252	  }
253	
254	  function handlePointerDown(event: React.PointerEvent<HTMLDivElement>) {
255	    if (!isZoomed || event.button !== 0) return;
256	    event.currentTarget.setPointerCapture(event.pointerId);
257	    dragRef.current = { pointerX: event.clientX, pointerY: event.clientY, origin: offset };
258	    setIsDragging(true);
259	  }
260	
261	  function handlePointerMove(event: React.PointerEvent<HTMLDivElement>) {
262	    const drag = dragRef.current;
263	    if (!drag || !shown || !frame) return;
264	    setPan(
265	      clampPan(
266	        {
267	          x: drag.origin.x + event.clientX - drag.pointerX,
268	          y: drag.origin.y + event.clientY - drag.pointerY,
269	        },
270	        shown,
271	        frame,
272	      ),
273	    );
274	  }
275	
276	  function endDrag() {
277	    dragRef.current = null;
278	    setIsDragging(false);
279	  }
280	
281	  return (
282	    <>
283	      <div
284	        ref={frameRef}
285	        className={`item-stage-zoom ${isZoomed ? "is-zoomed" : ""} ${isDragging ? "is-dragging" : ""}`}
286	        onPointerDown={handlePointerDown}
287	        onPointerMove={handlePointerMove}
288	        onPointerUp={endDrag}
289	        onPointerCancel={endDrag}
290	      >
291	        <img
292	          src={displayedSrc}
293	          alt={alt}
294	          className="item-stage-image"
295	          draggable={!isZoomed}
296	          onLoad={(event) => {
297	            const { naturalWidth, naturalHeight } = event.currentTarget;
298	            // Only the first load sets the layout; the original leaves it alone.
299	            if (naturalWidth > 0 && naturalHeight > 0) {
300	              setNatural((previous) => previous ?? { width: naturalWidth, height: naturalHeight });
301	            }
302	          }}
303	          style={{
304	            width: base?.width,
305	            height: base?.height,
306	            transform: isZoomed
307	              ? `translate(${offset.x}px, ${offset.y}px) scale(${zoom / fit})`
308	              : undefined,
309	            imageRendering: showPixels ? "pixelated" : undefined,
310	          }}
311	        />
312	        {showPixels && shown && (
313	          <div
314	            className="item-stage-grid"
315	            style={{
316	              width: shown.width,
317	              height: shown.height,
318	              translate: `calc(-50% + ${offset.x}px) calc(-50% + ${offset.y}px)`,
319	              backgroundSize: `${zoom / sourceScale}px ${zoom / sourceScale}px`,
320	            }}
321	          />
322	        )}
323	      </div>
324	      {ready && (
325	        <div className="item-zoom-pill glass">
326	          <button
327	            type="button"
328	            className="item-zoom-button"
329	            aria-label="Zoom out"
330	            title="Zoom out"
331	            disabled={!isZoomed}
332	            onClick={() => applyZoom(zoomOutLevel)}
333	          >
334	            <svg width="13" height="13" viewBox="0 0 24 24" aria-hidden="true">
335	              <path
336	                d="M5 12h14"
337	                fill="none"
338	                stroke="currentColor"
339	                strokeWidth="2.2"
340	                strokeLinecap="round"
341	              />
342	            </svg>
343	          </button>
344	          <span className="item-zoom-label">{Math.round(zoom * 100)}%</span>
345	          <button
346	            type="button"
347	            className="item-zoom-button"
348	            aria-label="Zoom in"
349	            title="Zoom in"
350	            disabled={nextStep === undefined}
351	            onClick={() => {
352	              if (nextStep !== undefined) applyZoom(nextStep);
353	            }}
354	          >
355	            <svg width="13" height="13" viewBox="0 0 24 24" aria-hidden="true">
356	              <path
357	                d="M12 5v14M5 12h14"
358	                fill="none"
359	                stroke="currentColor"
360	                strokeWidth="2.2"
361	                strokeLinecap="round"
362	              />
363	            </svg>
364	          </button>
365	        </div>
366	      )}
367	    </>
368	  );
369	}
