1	export type FlightRect = { left: number; top: number; width: number; height: number };
2	export type SourceRects = { card: FlightRect; media: FlightRect };
3	
4	export const OVERLAY_FLIGHT_MS = 600 * 0.85;
5	// GSAP's circ.inOut is the classic easeInOutCirc curve.
6	export const OVERLAY_EASE = "circ.inOut";
7	
8	export function prefersReducedMotion(): boolean {
9	  return (
10	    typeof window !== "undefined" && window.matchMedia("(prefers-reduced-motion: reduce)").matches
11	  );
12	}
13	
14	export function rectFrom(rect: DOMRect): FlightRect {
15	  return { left: rect.left, top: rect.top, width: rect.width, height: rect.height };
16	}
17	
18	const CARD_OFFSCREEN_THRESHOLD = 0.25;
19	
20	export function isCardTooFarOffscreen(card: FlightRect, viewport: FlightRect): boolean {
21	  if (card.width <= 0 || card.height <= 0) return true;
22	  const visibleWidth = Math.max(
23	    0,
24	    Math.min(card.left + card.width, viewport.left + viewport.width) -
25	      Math.max(card.left, viewport.left),
26	  );
27	  const visibleHeight = Math.max(
28	    0,
29	    Math.min(card.top + card.height, viewport.top + viewport.height) -
30	      Math.max(card.top, viewport.top),
31	  );
32	  const clippedWidth = 1 - visibleWidth / card.width;
33	  const clippedHeight = 1 - visibleHeight / card.height;
34	  return Math.max(clippedWidth, clippedHeight) > CARD_OFFSCREEN_THRESHOLD;
35	}
36	
37	export function scrollViewport(root: HTMLElement | null): HTMLElement | null {
38	  if (!root) return null;
39	  return root.querySelector<HTMLElement>('[data-testid="virtuoso-scroller"]') ?? root;
40	}
41	
42	// The floating toolbar covers the top of the grid, so a card only counts as
43	// visible below the toolbar's bottom edge.
44	export function scrollViewportRect(scroller: HTMLElement, toolbar: HTMLElement | null): FlightRect {
45	  const rect = rectFrom(scroller.getBoundingClientRect());
46	  const top = Math.max(rect.top, toolbar?.getBoundingClientRect().bottom ?? rect.top);
47	  return { ...rect, top, height: Math.max(0, rect.top + rect.height - top) };
48	}
49	
50	// Measures the live grid card for an item, if it is still mounted. Returns
51	// viewport coordinates so flights can run inside the fixed overlay layer.
52	export function queryCardRects(id: string | number): SourceRects | null {
53	  const card = document.querySelector<HTMLElement>(
54	    `.library-card[data-library-item-id="${CSS.escape(String(id))}"]`,
55	  );
56	  if (!card) return null;
57	  const cardRect = card.getBoundingClientRect();
58	  const mediaRect = card.querySelector<HTMLElement>(".library-card-media")?.getBoundingClientRect();
59	  return {
60	    card: rectFrom(cardRect),
61	    media: mediaRect ? rectFrom(mediaRect) : { ...rectFrom(cardRect), height: 0 },
